import re


_JOB_RE = re.compile(
    r"^JOB\s+(?P<name>\S+)\s+AT\s+(?P<at>\d{2}:\d{2})\s+"
    r"RUN\s+(?P<script>\S+)"
    r"(?:\s+ON_ERROR\s+(?P<error>ABORT|CONTINUE|RETRY:(?P<retries>\d+)))?$"
)


def parse_schedule(cfg_text: str) -> list[dict]:
    """Parse a Meridian CRM batch schedule into modern schedule entries."""
    entries = []

    for line_number, raw_line in enumerate(cfg_text.splitlines(), start=1):
        line = raw_line.strip()
        if not line or line.startswith("#"):
            continue

        match = _JOB_RE.fullmatch(line)
        if match is None:
            raise ValueError(f"Invalid schedule line {line_number}: {raw_line!r}")

        hours, minutes = (int(part) for part in match.group("at").split(":"))
        if hours > 23 or minutes > 59:
            raise ValueError(f"Invalid time on line {line_number}: {raw_line!r}")

        error_clause = match.group("error")
        if error_clause is None or error_clause == "ABORT":
            policy = "ABORT"
            retries = 0
        elif error_clause == "CONTINUE":
            policy = "CONTINUE"
            retries = 0
        else:
            policy = "RETRY"
            retries = int(match.group("retries"))

        entries.append(
            {
                "name": match.group("name"),
                "at": match.group("at"),
                "script": match.group("script"),
                "on_error": {
                    "policy": policy,
                    "retries": retries,
                },
            }
        )

    return entries
